1	// /auth — accounts and sessions (§3.5, §6): email/password register + login,
2	// server sessions in D1 behind an http-only cookie, Discord/Google OAuth
3	// (config-gated), and 501 stubs for the email-dependent flows.
4	//
5	// House style as everywhere: the pure logic lives in the sibling modules
6	// (password / session / oauth / rateLimit, all unit-tested); this file owns
7	// request validation, the D1 queries, and response shaping — every user
8	// payload boundary-parsed through @luminous/schema userSchema, which also
9	// guarantees no password/hash field can ever leak.
10	
11	import { zValidator } from "@hono/zod-validator";
12	import {
13	  loginRequestSchema,
14	  registerRequestSchema,
15	  updateProfileRequestSchema,
16	  type User,
17	  userSchema,
18	} from "@luminous/schema";
19	import { and, eq } from "drizzle-orm";
20	import { drizzle, type DrizzleD1Database } from "drizzle-orm/d1";
21	import { type Context, Hono } from "hono";
22	import type { z } from "zod";
23	import { oauthIdentities, sessions, users } from "../db/schema";
24	import { appOrigin, type Env } from "../env";
25	import { avatarSeedOf } from "./avatar";
26	import {
27	  buildAuthorizeUrl,
28	  clearedStateCookie,
29	  generateState,
30	  OAUTH_STATE_COOKIE,
31	  type OAuthProfile,
32	  type OAuthProvider,
33	  oauthConfig,
34	  packStateCookieValue,
35	  parseOAuthProfile,
36	  parseProvider,
37	  parseTokenResponse,
38	  sanitizeRedirect,
39	  stateCookie,
40	  tokenRequest,
41	  unpackStateCookieValue,
42	} from "./oauth";
43	import { DUMMY_PASSWORD_HASH, hashPassword, passwordNeedsRehash, verifyPassword } from "./password";
44	import { checkRateLimit, type RateLimitScope, rateLimitKey } from "./rateLimit";
45	import { requireUser } from "./requireUser";
46	import {
47	  clearedSessionCookie,
48	  generateSessionToken,
49	  hashSessionToken,
50	  readCookie,
51	  SESSION_COOKIE,
52	  SESSION_TTL_MS,
53	  sessionCookie,
54	} from "./session";
55	
56	export const authRoutes = new Hono<{ Bindings: Env }>();
57	
58	type Db = DrizzleD1Database;
59	type UserRow = typeof users.$inferSelect;
60	type AuthContext = Context<{ Bindings: Env }>;
61	
62	/** Row → public User (schema-parsed at each route's boundary). */
63	function mapUserRow(row: UserRow): User {
64	  return {
65	    id: row.id,
66	    email: row.email,
67	    displayName: row.displayName,
68	    emailVerified: row.emailVerified,
69	    // Derived, never stored (P5-2): the same token the lobby broadcasts for
70	    // this account, so a player's profile draws the face opponents see.
71	    avatarSeed: avatarSeedOf(row.id),
72	    createdAt: row.createdAt.toISOString(),
73	  };
74	}
75	
76	/** Terse 400 for bad request bodies, mirroring the catalog's invalid-query
77	    shape. zValidator surfaces the zod-core error type, hence z.core.$ZodError. */
78	function invalidBody(c: Context, error: z.core.$ZodError) {
79	  const issues = error.issues.map(
80	    (issue) => `${issue.path.map(String).join(".") || "body"}: ${issue.message}`,
81	  );
82	  return c.json({ error: "invalid body", issues }, 400);
83	}
84	
85	/** Best-effort caller IP for rate-limit keys — Cloudflare sets this header
86	    on every request (wrangler dev included). */
87	function clientIp(c: AuthContext): string {
88	  return c.req.header("cf-connecting-ip") ?? "unknown";
89	}
90	
91	/** Count this attempt; a 429 Response when over budget, null to proceed. */
92	async function guardRateLimit(
93	  c: AuthContext,
94	  scope: RateLimitScope,
95	  email: string,
96	): Promise<Response | null> {
97	  const decision = await checkRateLimit(c.env.CACHE, rateLimitKey(scope, clientIp(c), email));
98	  if (decision.allowed) {
99	    return null;
100	  }
101	  c.header("Retry-After", String(decision.retryAfterSeconds));
102	  return c.json({ error: "too many attempts" }, 429);
103	}
104	
105	/** Mint a token + its sessions row (id = sha256(token), 30-day expiry).
106	    The caller inserts the row — alone or inside a batch. */
107	async function newSession(userId: string) {
108	  const token = generateSessionToken();
109	  return {
110	    token,
111	    row: {
112	      id: await hashSessionToken(token),
113	      userId,
114	      expiresAt: new Date(Date.now() + SESSION_TTL_MS),
115	    },
116	  };
117	}
118	
119	/** D1 surfaces SQLite constraint failures as message text — good enough to
120	    turn a register/link race into a 409 instead of a 500. */
121	function isUniqueViolation(error: unknown): boolean {
122	  return error instanceof Error && error.message.includes("UNIQUE constraint failed");
123	}
124	
125	// --- email + password ------------------------------------------------------
126	
127	authRoutes.post(
128	  "/register",
129	  zValidator("json", registerRequestSchema, (result, c) =>
130	    result.success ? undefined : invalidBody(c, result.error),
131	  ),
132	  async (c) => {
133	    const body = c.req.valid("json");
134	    const limited = await guardRateLimit(c, "register", body.email);
135	    if (limited) {
136	      return limited;
137	    }
138	    const db = drizzle(c.env.DB);
139	    const existing = await db
140	      .select({ id: users.id })
141	      .from(users)
142	      .where(eq(users.email, body.email))
143	      .get();
144	    if (existing !== undefined) {
145	      return c.json({ error: "email already registered" }, 409);
146	    }
147	    const row: UserRow = {
148	      id: crypto.randomUUID(),
149	      email: body.email,
150	      // Default display name: the email's local part (user can rename later).
151	      displayName: body.displayName ?? body.email.split("@")[0] ?? body.email,
152	      passwordHash: await hashPassword(body.password),
153	      emailVerified: false,
154	      createdAt: new Date(),
155	    };
156	    const session = await newSession(row.id);
157	    try {
158	      await db.batch([db.insert(users).values(row), db.insert(sessions).values(session.row)]);
159	    } catch (error) {
160	      // Two concurrent registers for one email: the UNIQUE index catches what
161	      // the pre-check raced past.
162	      if (isUniqueViolation(error)) {
163	        return c.json({ error: "email already registered" }, 409);
164	      }
165	      throw error;
166	    }
167	    c.header("Set-Cookie", sessionCookie(session.token));
168	    return c.json(userSchema.parse(mapUserRow(row)), 201);
169	  },
170	);
171	
172	authRoutes.post(
173	  "/login",
174	  zValidator("json", loginRequestSchema, (result, c) =>
175	    result.success ? undefined : invalidBody(c, result.error),
176	  ),
177	  async (c) => {
178	    const body = c.req.valid("json");
179	    const limited = await guardRateLimit(c, "login", body.email);
180	    if (limited) {
181	      return limited;
182	    }
183	    const db = drizzle(c.env.DB);
184	    const row = await db.select().from(users).where(eq(users.email, body.email)).get();
185	    // Unknown email and password-less (OAuth-only) accounts still burn one
186	    // PBKDF2 verify against a throwaway hash — timing parity with the wrong-
187	    // password path, and ONE message for every failure (§3.5): no oracle for
188	    // which field was wrong.
189	    const verified = await verifyPassword(body.password, row?.passwordHash ?? DUMMY_PASSWORD_HASH);
190	    if (row === undefined || row.passwordHash === null || !verified) {
191	      return c.json({ error: "invalid email or password" }, 401);
192	    }
193	    // Iteration upgrade path: re-hash at today's DEFAULT_ITERATIONS while we
194	    // hold the plaintext.
195	    if (passwordNeedsRehash(row.passwordHash)) {
196	      await db
197	        .update(users)
198	        .set({ passwordHash: await hashPassword(body.password) })
199	        .where(eq(users.id, row.id));
200	    }
201	    const session = await newSession(row.id);
202	    await db.insert(sessions).values(session.row);
203	    c.header("Set-Cookie", sessionCookie(session.token));
204	    return c.json(userSchema.parse(mapUserRow(row)));
205	  },
206	);
207	
208	// --- session ----------------------------------------------------------------
209	
210	// Session resolution (cookie → user, expiry-on-read, lazy dead-row delete)
211	// lives in requireUser — shared with /decks and /folders (milestone 7); /me
212	// is just "echo the resolved caller".
213	authRoutes.get("/me", requireUser, (c) => c.json(userSchema.parse(mapUserRow(c.get("user")))));
214	
215	// Editing your own account (P5-5 — polish.md "Profiles"). The name P5-1 made
216	// authoritative was, until now, whatever register chose: the lobby broadcasts
217	// it to the opponent and to spectators, so being unable to change it is a real
218	// gap, not a nicety. requireUser runs BEFORE validation deliberately — a
219	// signed-out caller should hear "unauthorized", not a critique of their body.
220	authRoutes.patch(
221	  "/me",
222	  requireUser,
223	  zValidator("json", updateProfileRequestSchema, (result, c) =>
224	    result.success ? undefined : invalidBody(c, result.error),
225	  ),
226	  async (c) => {
227	    const row = c.get("user");
228	    const { displayName } = c.req.valid("json");
229	    // No write when nothing changed: the form disables Save in that case, but
230	    // the route is the api, and a re-submit shouldn't cost a D1 write.
231	    if (displayName !== row.displayName) {
232	      await drizzle(c.env.DB).update(users).set({ displayName }).where(eq(users.id, row.id));
233	    }
234	    // The updated row, not a re-read: this session owns the only change.
235	    return c.json(userSchema.parse(mapUserRow({ ...row, displayName })));
236	  },
237	);
238	
239	authRoutes.post("/logout", async (c) => {
240	  const token = readCookie(c.req.header("Cookie"), SESSION_COOKIE);
241	  if (token !== null) {
242	    await drizzle(c.env.DB)
243	      .delete(sessions)
244	      .where(eq(sessions.id, await hashSessionToken(token)));
245	  }
246	  c.header("Set-Cookie", clearedSessionCookie());
247	  return c.body(null, 204);
248	});
249	
250	// --- OAuth (Discord / Google) ------------------------------------------------
251	
252	/** Our callback URL on THIS deployment — derived from the request origin, so
253	    dev (localhost:8787) and prod (workers.dev) register their own URIs. */
254	function callbackUrl(c: AuthContext, provider: OAuthProvider): string {
255	  return `${new URL(c.req.url).origin}/auth/oauth/${provider}/callback`;
256	}
257	
258	authRoutes.get("/oauth/:provider", (c) => {
259	  const provider = parseProvider(c.req.param("provider"));
260	  if (provider === null) {
261	    return c.json({ error: "unknown provider" }, 404);
262	  }
263	  const config = oauthConfig(c.env, provider);
264	  if (config === null) {
265	    return c.json({ error: "provider not configured" }, 503);
266	  }
267	  const state = generateState();
268	  const redirect = sanitizeRedirect(c.req.query("redirect"));
269	  c.header("Set-Cookie", stateCookie(packStateCookieValue(state, redirect)));
270	  return c.redirect(buildAuthorizeUrl(config, callbackUrl(c, provider), state), 302);
271	});
272	
273	authRoutes.get("/oauth/:provider/callback", async (c) => {
274	  const provider = parseProvider(c.req.param("provider"));
275	  if (provider === null) {
276	    return c.json({ error: "unknown provider" }, 404);
277	  }
278	  const config = oauthConfig(c.env, provider);
279	  if (config === null) {
280	    return c.json({ error: "provider not configured" }, 503);
281	  }
282	  // The state cookie is single-use: cleared on every callback outcome.
283	  const packed = unpackStateCookieValue(readCookie(c.req.header("Cookie"), OAUTH_STATE_COOKIE));
284	  c.header("Set-Cookie", clearedStateCookie());
285	  const state = c.req.query("state");
286	  const code = c.req.query("code");
287	  if (!code || !state || packed === null || packed.state !== state) {
288	    return c.json({ error: "invalid oauth state" }, 400);
289	  }
290	
291	  // Code → access token.
292	  const exchange = tokenRequest(config, code, callbackUrl(c, provider));
293	  const tokenResponse = await fetch(exchange.url, {
294	    method: "POST",
295	    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
296	    body: exchange.body,
297	  });
298	  const accessToken = tokenResponse.ok ? parseTokenResponse(await tokenResponse.json()) : null;
299	  if (accessToken === null) {
300	    return c.json({ error: "oauth code exchange failed" }, 502);
301	  }
302	
303	  // Access token → normalized profile.
304	  const profileResponse = await fetch(config.userinfoUrl, {
305	    headers: { Authorization: `Bearer ${accessToken}` },
306	  });
307	  const profile = profileResponse.ok
308	    ? parseOAuthProfile(provider, await profileResponse.json())
309	    : null;
310	  if (profile === null) {
311	    return c.json({ error: "oauth profile fetch failed" }, 502);
312	  }
313	
314	  const db = drizzle(c.env.DB);
315	  const result = await findOrCreateOAuthUser(db, provider, profile);
316	  if (result === "no-email") {
317	    return c.json({ error: "provider did not supply an email" }, 400);
318	  }
319	  if (result === "email-in-use") {
320	    // The provider email matches an existing account but is NOT provider-
321	    // verified — linking would let anyone with an unverified alias take the
322	    // account over.
323	    return c.json({ error: "email already in use" }, 409);
324	  }
325	  const session = await newSession(result.id);
326	  await db.insert(sessions).values(session.row);
327	  c.header("Set-Cookie", sessionCookie(session.token), { append: true });
328	  return c.redirect(`${appOrigin(c.env)}${packed.redirect}`, 302);
329	});
330	
331	/** §3.5 find-or-create: linked identity → that user; verified-email match →
332	    link identity to the existing user; otherwise a fresh user + identity. */
333	async function findOrCreateOAuthUser(
334	  db: Db,
335	  provider: OAuthProvider,
336	  profile: OAuthProfile,
337	): Promise<UserRow | "no-email" | "email-in-use"> {
338	  const linked = await db
339	    .select({ user: users })
340	    .from(oauthIdentities)
341	    .innerJoin(users, eq(oauthIdentities.userId, users.id))
342	    .where(
343	      and(
344	        eq(oauthIdentities.provider, provider),
345	        eq(oauthIdentities.providerId, profile.providerId),
346	      ),
347	    )
348	    .get();
349	  if (linked !== undefined) {
350	    return linked.user;
351	  }
352	  if (profile.email === null) {
353	    // users.email is NOT NULL UNIQUE — nothing to key a new account on.
354	    return "no-email";
355	  }
356	  const identity = { provider, providerId: profile.providerId };
357	  const existing = await db.select().from(users).where(eq(users.email, profile.email)).get();
358	  if (existing !== undefined) {
359	    if (!profile.emailVerified) {
360	      return "email-in-use";
361	    }
362	    // Link, and promote emailVerified — the provider just attested it.
363	    await db.batch([
364	      db.insert(oauthIdentities).values({ ...identity, userId: existing.id }),
365	      db.update(users).set({ emailVerified: true }).where(eq(users.id, existing.id)),
366	    ]);
367	    return { ...existing, emailVerified: true };
368	  }
369	  const row: UserRow = {
370	    id: crypto.randomUUID(),
371	    email: profile.email,
372	    displayName: profile.displayName,
373	    passwordHash: null,
374	    emailVerified: profile.emailVerified,
375	    createdAt: new Date(),
376	  };
377	  await db.batch([
378	    db.insert(users).values(row),
379	    db.insert(oauthIdentities).values({ ...identity, userId: row.id }),
380	  ]);
381	  return row;
382	}
383	
384	// --- email-dependent flows: stubs -------------------------------------------
385	// TODO(§3.5): verify-email + reset-password need an outbound email provider,
386	// which is not chosen yet. Deliberately NO token tables/plumbing until it is
387	// — the 501s keep the §6 surface honest in the meantime.
388	
389	const EMAIL_NOT_IMPLEMENTED = {
390	  error: "not implemented",
391	  detail: "requires an outbound email provider, not yet chosen (backend-data.md §3.5)",
392	} as const;
393	
394	authRoutes.post("/verify-email", (c) => c.json(EMAIL_NOT_IMPLEMENTED, 501));
395	authRoutes.post("/reset-password", (c) => c.json(EMAIL_NOT_IMPLEMENTED, 501));
396

1	// P5-2 — the token an account's generated avatar is drawn from (polish.md
2	// "Lobby identity", the half P5-1 left). Pure, and deliberately tiny: there is no
3	// image here and nothing stored. The client draws a deterministic face from this
4	// string, so the same person looks the same to you in every lobby, and an
5	// account that later uploads a real picture just wins over it.
6	//
7	// It is a HASH of the account id rather than the id itself. Not because a uuid
8	// is guessable — it isn't — but because the lobby snapshot is BROADCAST (to the
9	// opponent, and since 3c-vii to spectators), and an internal primary key is the
10	// wrong thing to publish: it invites joining this seat to any other surface that
11	// happens to expose the same id. A hash keeps the one property the avatar needs
12	// (the same account always maps to the same face) and gives up the one it
13	// doesn't (being the account id).
14	//
15	// It lives under auth/ (not lobby/) since P5-5: the seed is a property of the
16	// ACCOUNT, not of a seat. /auth/me carries it so the profile shows a player the
17	// same face the lobby shows everyone else, and one hash serves both.
18	
19	/** FNV-1a, 32-bit, as 8 lowercase hex — a display token, not a security
20	    boundary, so the cheapest stable hash that spreads well is the right one; the
21	    client's only use is to pick colours from it. */
22	function fnv1a(input: string): string {
23	  let hash = 0x811c9dc5;
24	  for (let i = 0; i < input.length; i++) {
25	    hash ^= input.charCodeAt(i);
26	    // The FNV prime, via shifts — `* 16777619` overflows a JS number's integer
27	    // range and would stop being the same function on long inputs.
28	    hash = (hash + ((hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24))) >>> 0;
29	  }
30	  return hash.toString(16).padStart(8, "0");
31	}
32	
33	/** The avatar token of an account. Every account has one — it's derived, not
34	    stored, so there is no "not set yet" case to represent. */
35	export function avatarSeedOf(userId: string): string {
36	  return fnv1a(userId);
37	}
38	
39	/** The same token for a caller that may have no account: null for an anonymous
40	    socket, which renders the generic figure — honestly saying "we don't know who
41	    this is" rather than inventing a face from a throwaway id that would change
42	    on every visit. */
43	export function avatarSeedFrom(userId: string | null): string | null {
44	  return userId === null ? null : avatarSeedOf(userId);
45	}
46

1	// requireUser — the shared "who is calling" gate (§3.5), extracted in P1
2	// milestone 7 so /auth/me and the /decks + /folders routes resolve sessions
3	// through ONE code path: read the `session` cookie, hash the token to the
4	// sessions row id, join the user, enforce expiry on read (deleting the dead
5	// row lazily), and either stash the user row on the context or answer 401.
6	//
7	// The cookie is cleared only when a token WAS presented but didn't resolve —
8	// a cookie-less request gets a bare 401 without touching D1, which is also
9	// what lets route tests prove the gate runs before any query.
10	
11	import { eq } from "drizzle-orm";
12	import { drizzle } from "drizzle-orm/d1";
13	import { createMiddleware } from "hono/factory";
14	import { sessions, users } from "../db/schema";
15	import type { Env } from "../env";
16	import { clearedSessionCookie, hashSessionToken, readCookie, SESSION_COOKIE } from "./session";
17	
18	export type UserRow = typeof users.$inferSelect;
19	
20	/** Hono env for routes behind requireUser: `c.get("user")` is the caller. */
21	export type AuthedEnv = { Bindings: Env; Variables: { user: UserRow } };
22	
23	export const requireUser = createMiddleware<AuthedEnv>(async (c, next) => {
24	  const token = readCookie(c.req.header("Cookie"), SESSION_COOKIE);
25	  if (token === null) {
26	    return c.json({ error: "unauthorized" }, 401);
27	  }
28	  const sessionId = await hashSessionToken(token);
29	  const db = drizzle(c.env.DB);
30	  const row = await db
31	    .select({ user: users, expiresAt: sessions.expiresAt })
32	    .from(sessions)
33	    .innerJoin(users, eq(sessions.userId, users.id))
34	    .where(eq(sessions.id, sessionId))
35	    .get();
36	  if (row === undefined) {
37	    c.header("Set-Cookie", clearedSessionCookie());
38	    return c.json({ error: "unauthorized" }, 401);
39	  }
40	  // Expiry enforced on read; the dead row is deleted lazily right here —
41	  // no background sweeper needed at this scale.
42	  if (row.expiresAt.getTime() <= Date.now()) {
43	    await db.delete(sessions).where(eq(sessions.id, sessionId));
44	    c.header("Set-Cookie", clearedSessionCookie());
45	    return c.json({ error: "unauthorized" }, 401);
46	  }
47	  c.set("user", row.user);
48	  await next();
49	});
