content.content:
1	// /decks + /folders — the authenticated deck library (P1 milestone 7, §6).
2	//
3	// House style as everywhere: pure helpers in the sibling modules (map.ts /
4	// validate.ts, unit-tested); this file owns request validation, the D1
5	// queries, and response shaping — every payload boundary-parsed through the
6	// @luminous/schema deck/folder schemas. NO KV cache on any of it: user data
7	// must read fresh (§6).
8	//
9	// Per-route chain order is zValidator → requireUser → handler: body shape
10	// checks are pure (testable with no DB at all), then the session gate, then
11	// data. Every :id lookup is scoped `WHERE user_id = ?` — someone else's
12	// resource answers the SAME 404 as a missing one (no existence leak), while
13	// a folderId/parentId reference you don't own is a 400 (it's YOUR request
14	// body that's wrong, and it never names a specific victim).
15	
16	import { zValidator } from "@hono/zod-validator";
17	import {
18	  createDeckRequestSchema,
19	  createFolderRequestSchema,
20	  type DeckCard,
21	  deckSchema,
22	  deckSummarySchema,
23	  folderSchema,
24	  patchDeckRequestSchema,
25	  patchFolderRequestSchema,
26	  type ReorderRequest,
27	  reorderRequestSchema,
28	} from "@luminous/schema";
29	import { and, asc, eq, inArray, sql } from "drizzle-orm";
30	import type { BatchItem } from "drizzle-orm/batch";
31	import { drizzle, type DrizzleD1Database } from "drizzle-orm/d1";
32	import { type Context, Hono } from "hono";
33	import { z } from "zod";
34	import { requireUser } from "../auth/requireUser";
35	import { cards, deckCards, decks, folders } from "../db/schema";
36	import type { Env } from "../env";
37	import { type CoverCandidate, effectiveCoverCardId } from "./cover";
38	import { type DeckRow, type FolderRow, mapDeckRow, mapDeckSummaryRow, mapFolderRow } from "./map";
39	import { chunk, createsCycle, D1_MAX_BOUND_PARAMS, unknownIds } from "./validate";
40	
41	export const deckRoutes = new Hono<{ Bindings: Env }>();
42	export const folderRoutes = new Hono<{ Bindings: Env }>();
43	
44	type Db = DrizzleD1Database;
45	type Batch = [BatchItem<"sqlite">, ...BatchItem<"sqlite">[]];
46	
47	// Response schemas — the domain shapes each route parses itself against.
48	const deckSummariesResponseSchema = z.array(deckSummarySchema);
49	const foldersResponseSchema = z.array(folderSchema);
50	
51	/** Terse 400 for bad request bodies (the auth/catalog shape). zValidator
52	    surfaces the zod-core error type, hence z.core.$ZodError. */
53	function invalidBody(c: Context, error: z.core.$ZodError) {
54	  const issues = error.issues.map(
55	    (issue) => `${issue.path.map(String).join(".") || "body"}: ${issue.message}`,
56	  );
57	  return c.json({ error: "invalid body", issues }, 400);
58	}
59	
60	const validateBody = <Schema extends z.ZodType>(schema: Schema) =>
61	  zValidator("json", schema, (result, c) =>
62	    result.success ? undefined : invalidBody(c, result.error),
63	  );
64	
65	/** 400 when `folderId` names a folder the CALLER doesn't own — a folder that
66	    doesn't exist at all gets the same answer, so nothing about other users'
67	    trees leaks. Null (the library root) always passes. */
68	async function guardFolderRef(
69	  c: Context,
70	  db: Db,
71	  userId: string,
72	  folderId: string | null | undefined,
73	): Promise<Response | null> {
74	  if (folderId === null || folderId === undefined) {
75	    return null;
76	  }
77	  const row = await db
78	    .select({ id: folders.id })
79	    .from(folders)
80	    .where(and(eq(folders.id, folderId), eq(folders.userId, userId)))
81	    .get();
82	  return row === undefined ? c.json({ error: "unknown folder" }, 400) : null;
83	}
84	
85	/** 400 naming the card ids absent from the catalog, or null when all exist.
86	    One logical IN query — chunked to D1's bound-parameter cap and run in a
87	    single db.batch round trip — instead of relying on FK error text. */
88	async function guardUnknownCards(
89	  c: Context,
90	  db: Db,
91	  entries: readonly DeckCard[],
92	): Promise<Response | null> {
93	  if (entries.length === 0) {
94	    return null;
95	  }
96	  const ids = entries.map((entry) => entry.cardId);
97	  const queries: BatchItem<"sqlite">[] = chunk(ids, D1_MAX_BOUND_PARAMS).map((group) =>
98	    db.select({ id: cards.id }).from(cards).where(inArray(cards.id, group)),
99	  );
100	  const results = (await db.batch(queries as Batch)) as { id: string }[][];
101	  const unknown = unknownIds(
102	    ids,
103	    results.flat().map((row) => row.id),
104	  );
105	  return unknown.length === 0
106	    ? null
107	    : c.json({ error: "unknown card id(s)", cardIds: unknown }, 400);
108	}
109	
110	/** The `position` a created deck/folder takes: one below the user's current
111	    minimum, so new rows land FIRST in the position-ordered lists (the web
112	    grid prepends creates). Two racing creates can tie — harmless, the id
113	    tiebreak keeps the order stable. */
114	async function nextPrependPosition(
115	  db: Db,
116	  table: typeof decks | typeof folders,
117	  userId: string,
118	): Promise<number> {
119	  const row = await db
120	    .select({ min: sql<number | null>`min(${table.position})` })
121	    .from(table)
122	    .where(eq(table.userId, userId))
123	    .get();
124	  return (row?.min ?? 1) - 1;
125	}
126	
127	/** Both reorder routes: absolute position assignments, applied atomically in
128	    one batch. Any id that isn't the CALLER's answers a 400 naming it (the
129	    ids came from the request body, and a foreign id reads the same as a
130	    missing one — no existence leak). */
131	async function reorderRows(
132	  c: Context,
133	  db: Db,
134	  table: typeof decks | typeof folders,
135	  noun: "deck" | "folder",
136	  userId: string,
137	  positions: ReorderRequest["positions"],
138	): Promise<Response> {
139	  const ids = positions.map((entry) => entry.id);
140	  const queries: BatchItem<"sqlite">[] = chunk(ids, D1_MAX_BOUND_PARAMS - 1).map((group) =>
141	    db
142	      .select({ id: table.id })
143	      .from(table)
144	      .where(and(eq(table.userId, userId), inArray(table.id, group))),
145	  );
146	  const owned = (await db.batch(queries as Batch)) as { id: string }[][];
147	  const unknown = unknownIds(
148	    ids,
149	    owned.flat().map((row) => row.id),
150	  );
151	  if (unknown.length > 0) {
152	    return c.json({ error: `unknown ${noun} id(s)`, ids: unknown }, 400);
153	  }
154	  const updates: BatchItem<"sqlite">[] = positions.map(({ id, position }) =>
155	    db.update(table).set({ position }).where(eq(table.id, id)),
156	  );
157	  await db.batch(updates as Batch);
158	  return c.body(null, 204);
159	}
160	
161	/** Chunked `deck_cards` inserts for one deck (3 bound params per row). */
162	function deckCardInserts(db: Db, deckId: string, entries: readonly DeckCard[]) {
163	  const rowsPerInsert = Math.floor(D1_MAX_BOUND_PARAMS / 3);
164	  return chunk(entries, rowsPerInsert).map((group) =>
165	    db.insert(deckCards).values(group.map(({ cardId, count }) => ({ deckId, cardId, count }))),
166	  );
167	}
168	
169	/** The (already user-scoped) card list of one deck, in stable id order. */
170	function selectDeckCards(db: Db, deckId: string) {
171	  return db
172	    .select({ cardId: deckCards.cardId, count: deckCards.count })
173	    .from(deckCards)
174	    .where(eq(deckCards.deckId, deckId))
175	    .orderBy(asc(deckCards.cardId));
176	}
177	
178	// --- decks -------------------------------------------------------------------
179	
180	deckRoutes.get("/", requireUser, async (c) => {
181	  const db = drizzle(c.env.DB);
182	  const userId = c.get("user").id;
183	  const rows = await db
184	    .select({ deck: decks, cardCount: sql<number>`coalesce(sum(${deckCards.count}), 0)` })
185	    .from(decks)
186	    .leftJoin(deckCards, eq(deckCards.deckId, decks.id))
187	    .where(eq(decks.userId, userId))
188	    .groupBy(decks.id)
189	    .orderBy(asc(decks.position), asc(decks.id))
190	    .all();
191	  // Cover candidates for the whole library in ONE query (P5-3), rather than the
192	  // window function this would need to fold into the aggregate above: the RULE
193	  // then lives in a pure `pickCoverCardId` that can be argued with and tested,
194	  // and the extra rows are one per distinct card per deck.
195	  const candidateRows = await db
196	    .select({
197	      deckId: deckCards.deckId,
198	      cardId: deckCards.cardId,
199	      count: deckCards.count,
200	      category: cards.category,
201	      hp: cards.hp,
202	      imageUrl: cards.imageUrl,
203	    })
204	    .from(deckCards)
205	    .innerJoin(decks, eq(decks.id, deckCards.deckId))
206	    .innerJoin(cards, eq(cards.id, deckCards.cardId))
207	    .where(eq(decks.userId, userId))
208	    .all();
209	  const byDeck = new Map<string, CoverCandidate[]>();
210	  for (const row of candidateRows) {
211	    const list = byDeck.get(row.deckId) ?? [];
212	    list.push({
213	      cardId: row.cardId,
214	      count: row.count,
215	      category: row.category,
216	      hp: row.hp,
217	      hasImage: row.imageUrl !== null,
218	    });
219	    byDeck.set(row.deckId, list);
220	  }
221	  return c.json(
222	    deckSummariesResponseSchema.parse(
223	      rows.map((row) =>
224	        mapDeckSummaryRow(
225	          row.deck,
226	          row.cardCount,
227	          // The owner's pin wins over the derived default, but only while it is
228	          // still a drawable card in the deck (P5-6) — resolved against the
229	          // candidates already in hand, so honouring a choice costs no query.
230	          effectiveCoverCardId(row.deck.coverCardId, byDeck.get(row.deck.id) ?? []),
231	        ),
232	      ),
233	    ),
234	  );
235	});
236	
237	deckRoutes.get("/:id", requireUser, async (c) => {
238	  const deckId = c.req.param("id");
239	  const db = drizzle(c.env.DB);
240	  const [deckRows, cardRows] = await db.batch([
241	    db
242	      .select()
243	      .from(decks)
244	      .where(and(eq(decks.id, deckId), eq(decks.userId, c.get("user").id))),
245	    selectDeckCards(db, deckId),
246	  ]);
247	  const row = deckRows[0];
248	  if (row === undefined) {
249	    return c.json({ error: "deck not found" }, 404);
250	  }
251	  return c.json(deckSchema.parse(mapDeckRow(row, cardRows)));
252	});
253	
254	deckRoutes.post("/", validateBody(createDeckRequestSchema), requireUser, async (c) => {
255	  const body = c.req.valid("json");
256	  const user = c.get("user");
257	  const db = drizzle(c.env.DB);
258	  const badFolder = await guardFolderRef(c, db, user.id, body.folderId);
259	  if (badFolder !== null) {
260	    return badFolder;
261	  }
262	  const badCards = await guardUnknownCards(c, db, body.cards);
263	  if (badCards !== null) {
264	    return badCards;
265	  }
266	  const row: DeckRow = {
267	    id: crypto.randomUUID(),
268	    userId: user.id,
269	    folderId: body.folderId ?? null,
270	    name: body.name,
271	    format: body.format ?? null,
272	    tint: body.tint,
273	    // A brand-new deck wears the derived default; picking a cover is an edit
274	    // you make later, in the editor, once there is something to pick.
275	    coverCardId: null,
276	    position: await nextPrependPosition(db, decks, user.id),
277	    updated: new Date(),
278	  };
279	  await db.batch([
280	    db.insert(decks).values(row),
281	    ...deckCardInserts(db, row.id, body.cards),
282	  ] as Batch);
283	  return c.json(deckSchema.parse(mapDeckRow(row, body.cards)), 201);
284	});
285	
286	deckRoutes.patch("/:id", validateBody(patchDeckRequestSchema), requireUser, async (c) => {
287	  const body = c.req.valid("json");
288	  const user = c.get("user");
289	  const deckId = c.req.param("id");
290	  const db = drizzle(c.env.DB);
291	  const existing = await db
292	    .select()
293	    .from(decks)
294	    .where(and(eq(decks.id, deckId), eq(decks.userId, user.id)))
295	    .get();
296	  if (existing === undefined) {
297	    return c.json({ error: "deck not found" }, 404);
298	  }
299	  const badFolder = await guardFolderRef(c, db, user.id, body.folderId);
300	  if (badFolder !== null) {
301	    return badFolder;
302	  }
303	  const badCards = await guardUnknownCards(c, db, body.cards ?? []);
304	  if (badCards !== null) {
305	    return badCards;
306	  }
307	  // A cover pin must name a card the deck still runs (P5-6) — and `cards` can
308	  // be replaced by this same request, so the list it has to live in is the one
309	  // the patch LEAVES BEHIND. Read only when a pin is actually in play, so the
310	  // ordinary rename/move patch costs nothing.
311	  const pinInPlay =
312	    (body.chosenCoverCardId ?? null) !== null ||
313	    (existing.coverCardId !== null && body.cards !== undefined);
314	  const cardIdsAfter = pinInPlay
315	    ? new Set((body.cards ?? (await selectDeckCards(db, deckId).all())).map((e) => e.cardId))
316	    : null;
317	  let coverCardId = existing.coverCardId;
318	  if (body.chosenCoverCardId !== undefined) {
319	    // Explicit: a card id pins it, null goes back to the derived default.
320	    coverCardId = body.chosenCoverCardId;
321	    if (coverCardId !== null && cardIdsAfter?.has(coverCardId) !== true) {
322	      return c.json({ error: "cover card not in deck", cardIds: [coverCardId] }, 400);
323	    }
324	  } else if (coverCardId !== null && cardIdsAfter !== null && !cardIdsAfter.has(coverCardId)) {
325	    // The pinned card left the deck in this patch, so the choice goes with it
326	    // rather than lingering as a pin nothing can honour.
327	    coverCardId = null;
328	  }
329	  const next: DeckRow = {
330	    ...existing,
331	    name: body.name ?? existing.name,
332	    tint: body.tint ?? existing.tint,
333	    // For the nullable fields, absent means "keep" and null means "clear".
334	    format: body.format === undefined ? existing.format : body.format,
335	    folderId: body.folderId === undefined ? existing.folderId : body.folderId,
336	    coverCardId,
337	    updated: new Date(),
338	  };
339	  const statements: BatchItem<"sqlite">[] = [
340	    db
341	      .update(decks)
342	      .set({
343	        name: next.name,
344	        tint: next.tint,
345	        format: next.format,
346	        folderId: next.folderId,
347	        coverCardId: next.coverCardId,
348	        updated: next.updated,
349	      })
350	      .where(eq(decks.id, deckId)),
351	  ];
352	  if (body.cards !== undefined) {
353	    // Wholesale replacement: delete + reinsert atomically in the same batch.
354	    statements.push(db.delete(deckCards).where(eq(deckCards.deckId, deckId)));
355	    statements.push(...deckCardInserts(db, deckId, body.cards));
356	  }
357	  await db.batch(statements as Batch);
358	  const cardsAfter = body.cards ?? (await selectDeckCards(db, deckId).all());
359	  return c.json(deckSchema.parse(mapDeckRow(next, cardsAfter)));
360	});
361	
362	deckRoutes.post("/reorder", validateBody(reorderRequestSchema), requireUser, async (c) => {
363	  return reorderRows(
364	    c,
365	    drizzle(c.env.DB),
366	    decks,
367	    "deck",
368	    c.get("user").id,
369	    c.req.valid("json").positions,
370	  );
371	});
372	
373	deckRoutes.delete("/:id", requireUser, async (c) => {
374	  const deleted = await drizzle(c.env.DB)
375	    .delete(decks)
376	    .where(and(eq(decks.id, c.req.param("id")), eq(decks.userId, c.get("user").id)))
377	    .returning({ id: decks.id });
378	  if (deleted.length === 0) {
379	    return c.json({ error: "deck not found" }, 404);
380	  }
381	  // deck_cards rows cascade away with the deck (§5.3 FKs).
382	  return c.body(null, 204);
383	});
384	
385	// --- folders -----------------------------------------------------------------
386	
387	folderRoutes.get("/", requireUser, async (c) => {
388	  const rows = await drizzle(c.env.DB)
389	    .select()
390	    .from(folders)
391	    .where(eq(folders.userId, c.get("user").id))
392	    .orderBy(asc(folders.position), asc(folders.id))
393	    .all();
394	  return c.json(foldersResponseSchema.parse(rows.map(mapFolderRow)));
395	});
396	
397	folderRoutes.post("/", validateBody(createFolderRequestSchema), requireUser, async (c) => {
398	  const body = c.req.valid("json");
399	  const user = c.get("user");
400	  const db = drizzle(c.env.DB);
401	  const badParent = await guardFolderRef(c, db, user.id, body.parentId);
402	  if (badParent !== null) {
403	    return badParent;
404	  }
405	  const row: FolderRow = {
406	    id: crypto.randomUUID(),
407	    userId: user.id,
408	    parentId: body.parentId ?? null,
409	    name: body.name,
410	    position: await nextPrependPosition(db, folders, user.id),
411	  };
412	  await db.insert(folders).values(row);
413	  return c.json(folderSchema.parse(mapFolderRow(row)), 201);
414	});
415	
416	folderRoutes.patch("/:id", validateBody(patchFolderRequestSchema), requireUser, async (c) => {
417	  const body = c.req.valid("json");
418	  const user = c.get("user");
419	  const folderId = c.req.param("id");
420	  const db = drizzle(c.env.DB);
421	  // One user's folder list is small; fetch it whole — the ownership check,
422	  // the parent-reference check and the cycle walk all read the same rows.
423	  const rows = await db.select().from(folders).where(eq(folders.userId, user.id)).all();
424	  const target = rows.find((row) => row.id === folderId);
425	  if (target === undefined) {
426	    return c.json({ error: "folder not found" }, 404);
427	  }
428	  if (body.parentId !== undefined && body.parentId !== null) {
429	    if (!rows.some((row) => row.id === body.parentId)) {
430	      return c.json({ error: "unknown folder" }, 400);
431	    }
432	    const parents = new Map(rows.map((row) => [row.id, row.parentId]));
433	    if (createsCycle(parents, folderId, body.parentId)) {
434	      return c.json({ error: "cannot move a folder into itself or its own subtree" }, 400);
435	    }
436	  }
437	  const next: FolderRow = {
438	    ...target,
439	    name: body.name ?? target.name,
440	    parentId: body.parentId === undefined ? target.parentId : body.parentId,
441	  };
442	  await db
443	    .update(folders)
444	    .set({ name: next.name, parentId: next.parentId })
445	    .where(eq(folders.id, folderId));
446	  return c.json(folderSchema.parse(mapFolderRow(next)));
447	});
448	
449	folderRoutes.post("/reorder", validateBody(reorderRequestSchema), requireUser, async (c) => {
450	  return reorderRows(
451	    c,
452	    drizzle(c.env.DB),
453	    folders,
454	    "folder",
455	    c.get("user").id,
456	    c.req.valid("json").positions,
457	  );
458	});
459	
460	folderRoutes.delete("/:id", requireUser, async (c) => {
461	  const deleted = await drizzle(c.env.DB)
462	    .delete(folders)
463	    .where(and(eq(folders.id, c.req.param("id")), eq(folders.userId, c.get("user").id)))
464	    .returning({ id: folders.id });
465	  if (deleted.length === 0) {
466	    return c.json({ error: "folder not found" }, 404);
467	  }
468	  // §5.3 FK semantics do the rest: subfolders cascade-delete with the parent,
469	  // and decks inside any deleted folder fall back to the library root
470	  // (folder_id SET NULL) — decks are never destroyed by folder deletion.
471	  return c.body(null, 204);
472	});
473

1	// Auth request bodies (backend-data.md §3.5/§6) — parsed by the api's
2	// zValidator at the boundary and reusable by the web app's forms.
3	
4	import { z } from "zod";
5	
6	/** Emails are normalized to lowercase AT the boundary: `users.email` is
7	    UNIQUE and every lookup is exact, so one canonical casing everywhere. */
8	const emailField = z
9	  .email()
10	  .max(254)
11	  .transform((value) => value.toLowerCase());
12	
13	/** Password policy lives on REGISTER only (min 8); login accepts anything
14	    non-empty so a policy change never locks out existing accounts. The max
15	    is a DoS guard — every char feeds PBKDF2. */
16	const newPasswordField = z.string().min(8).max(256);
17	
18	export const registerRequestSchema = z.object({
19	  email: emailField,
20	  password: newPasswordField,
21	  displayName: z.string().trim().min(1).max(64).optional(),
22	});
23	export type RegisterRequest = z.infer<typeof registerRequestSchema>;
24	
25	export const loginRequestSchema = z.object({
26	  email: emailField,
27	  password: z.string().min(1).max(256),
28	});
29	export type LoginRequest = z.infer<typeof loginRequestSchema>;
30	
31	/** Editing your own profile (P5-5). Same 1–64 bounds as register's optional
32	    name, but REQUIRED here: register may omit it and get the email's local
33	    part, while explicitly saving a blank one would only cost you your name —
34	    the lobby would fall back to a generated "Player 4271" handle (P5-1). */
35	export const updateProfileRequestSchema = z.object({
36	  displayName: z.string().trim().min(1).max(64),
37	});
38	export type UpdateProfileRequest = z.infer<typeof updateProfileRequestSchema>;
39

1	// P5-3 — which card is a deck's face in the library grid (polish.md "Deck covers
2	// / art"). Until now every deck rendered the same blue card back under a
3	// generated tint; the catalog has had real scans since P2.
4	//
5	// The whole RULE lives in this pure function rather than in SQL, so it can be
6	// argued with and tested. The query half hands it every card in a deck with the
7	// three facts the rule needs.
8	
9	/** One deck row, joined to what the catalog knows about the card. */
10	export type CoverCandidate = {
11	  cardId: string;
12	  /** Copies in the deck. */
13	  count: number;
14	  /** "Pokemon" | "Trainer" | "Energy" — only Pokémon can be a cover. */
15	  category: string;
16	  /** Printed HP; null on Trainers and Energy. */
17	  hp: number | null;
18	  /** Whether the catalog has a scan for it (`cards.image_url`). */
19	  hasImage: boolean;
20	};
21	
22	/** A deck's cover card, or null when nothing in it qualifies (an empty deck, or
23	    one with no Pokémon scan yet) — the caller falls back to the card back, which
24	    is also exactly right for a deck you have only just created.
25	
26	    **The rule: the Pokémon with the highest printed HP.** HP is the best proxy
27	    the catalog offers for "the card this deck is built around", and it is a
28	    single number rather than a taxonomy to interpret: an ex/V/VMAX or a Stage 2
29	    outranks the Basics that fetch it, WITHOUT needing to rank the `stage` values
30	    against each other — which is what makes it beat the obvious alternatives.
31	    Ranking by STAGE alone gets a Basic-ex deck wrong (a 330 HP Basic ex is the
32	    deck's payoff, and would lose to any Stage 2 tech line); ranking by COUNT
33	    alone gets almost every evolution deck wrong (the 4-of Basic beats the 3-of
34	    Stage 2 it evolves into). Count still breaks HP ties, so between two equal
35	    bodies the one the deck actually runs more of wins, and the card id breaks
36	    the rest so the same deck always shows the same face.
37	
38	    It is a HEURISTIC and will occasionally pick a wall over the attacker beside
39	    it. That is acceptable for a DEFAULT — since P5-6 the owner can pin their own
40	    (see `effectiveCoverCardId`), and this is what a deck wears until they do.
41	    Cards with no scan are skipped rather than picked and rendered blank. */
42	export function pickCoverCardId(candidates: readonly CoverCandidate[]): string | null {
43	  let best: CoverCandidate | null = null;
44	  for (const candidate of candidates) {
45	    if (candidate.category !== "Pokemon" || !candidate.hasImage) continue;
46	    if (best === null || outranks(candidate, best)) best = candidate;
47	  }
48	  return best === null ? null : best.cardId;
49	}
50	
51	/** The card a deck's grid tile actually draws: **the owner's pick wins**, and
52	    everything else falls back to the derived default.
53	
54	    P5-6 — the follow-up P5-3 left room for. The pin is honoured only while it
55	    names a card that is still IN the deck and still has a scan, which is why
56	    this is a resolution rather than a plain `??`. PATCH keeps the first half
57	    true (a pinned card removed from the deck drops the pin with it), so the
58	    membership check here is a belt-and-braces on a row edited by some other
59	    path — but the SCAN half is live: the catalog is re-ingested, and a deck must
60	    never front a blank rectangle because a picture moved. Both checks run
61	    against the candidate list the default is derived from anyway, so honouring
62	    a choice costs no query at all. */
63	export function effectiveCoverCardId(
64	  chosen: string | null,
65	  candidates: readonly CoverCandidate[],
66	): string | null {
67	  const pinned = candidates.find((candidate) => candidate.cardId === chosen);
68	  // A pinned TRAINER or ENERGY is fine here — the owner is allowed a signature
69	  // Supporter as their deck's face; only the DERIVED default is Pokémon-only,
70	  // because guessing needs a rule and choosing does not.
71	  if (pinned?.hasImage) return pinned.cardId;
72	  return pickCoverCardId(candidates);
73	}
74	
75	/** Strictly better cover than `best`: more HP, else more copies, else the lower
76	    card id — a total order, so the pick never depends on row order. */
77	function outranks(candidate: CoverCandidate, best: CoverCandidate): boolean {
78	  const hp = candidate.hp ?? 0;
79	  const bestHp = best.hp ?? 0;
80	  if (hp !== bestHp) return hp > bestHp;
81	  if (candidate.count !== best.count) return candidate.count > best.count;
82	  return candidate.cardId < best.cardId;
83	}
84

1	// D1 row → deck-library domain mapping (P1 milestone 7, §5.2/§6) — the
2	// catalog/map.ts pattern: pure functions from Drizzle rows to the shapes in
3	// @luminous/schema/decks, so routes.ts owns queries and these unit-test flat.
4	// `user_id` never crosses the boundary — ownership is a WHERE clause, not a
5	// response field — and the epoch-ms `updated` column serializes to ISO here.
6	
7	import type { Deck, DeckCard, DeckSummary, Folder } from "@luminous/schema";
8	import type { decks, folders } from "../db/schema";
9	
10	export type FolderRow = typeof folders.$inferSelect;
11	export type DeckRow = typeof decks.$inferSelect;
12	
13	export function mapFolderRow(row: FolderRow): Folder {
14	  return { id: row.id, name: row.name, parentId: row.parentId, position: row.position };
15	}
16	
17	/** The shared (cards-free) projection of a deck row. */
18	function mapDeckBase(row: DeckRow) {
19	  return {
20	    id: row.id,
21	    name: row.name,
22	    format: row.format,
23	    tint: row.tint,
24	    folderId: row.folderId,
25	    position: row.position,
26	    updated: row.updated.toISOString(),
27	  };
28	}
29	
30	/** Full deck: the row plus its (already user-scoped) deck_cards entries.
31	    `chosenCoverCardId` is the STORED pin (P5-6) — the editor's state, null for
32	    automatic — not the face being drawn, which is the summary's business. */
33	export function mapDeckRow(row: DeckRow, cards: readonly DeckCard[]): Deck {
34	  return {
35	    ...mapDeckBase(row),
36	    cards: cards.map(({ cardId, count }) => ({ cardId, count })),
37	    chosenCoverCardId: row.coverCardId,
38	  };
39	}
40	
41	/** List row: `cardCount` is the SQL-side sum of the deck's copy counts, and
42	    `coverCardId` the deck's face (P5-3 — `pickCoverCardId`, null for a deck with
43	    nothing to show). */
44	export function mapDeckSummaryRow(
45	  row: DeckRow,
46	  cardCount: number,
47	  coverCardId: string | null,
48	): DeckSummary {
49	  return { ...mapDeckBase(row), cardCount, coverCardId };
50	}
51

