1	import {
2	  createContext,
3	  type ReactNode,
4	  useCallback,
5	  useContext,
6	  useEffect,
7	  useMemo,
8	  useRef,
9	  useState,
10	} from "react";
11	import type { LoginRequest, RegisterRequest, UpdateProfileRequest, User } from "@luminous/schema";
12	import {
13	  ApiError,
14	  login as apiLogin,
15	  logout as apiLogout,
16	  me as apiMe,
17	  register as apiRegister,
18	  updateProfile as apiUpdateProfile,
19	  setSessionRecoveryHandler,
20	} from "../../lib/api";
21	
22	/** Where the session stands. "loading" only during the mount-time `me()`
23	    probe (and manual `refresh()`); after that it's a hard either/or. */
24	export type AuthStatus = "loading" | "authenticated" | "anonymous";
25	
26	type AuthContextValue = {
27	  status: AuthStatus;
28	  /** Non-null exactly when status === "authenticated". */
29	  user: User | null;
30	  /** True when the last session probe failed for a reason OTHER than a clean
31	      401 (network down, api unreachable) — we treat that as anonymous, but a
32	      caller can distinguish "signed out" from "couldn't ask". */
33	  probeFailed: boolean;
34	  /** Wrappers around the api client that also update this context. They let
35	      ApiError propagate so forms can map `.status` to friendly copy. */
36	  login: (body: LoginRequest) => Promise<User>;
37	  register: (body: RegisterRequest) => Promise<User>;
38	  logout: () => Promise<void>;
39	  /** Save profile edits (P5-5) and adopt the api's answer as the current user,
40	      so every surface reading it — the corner control's initial, the generated
41	      avatar — follows without a re-probe. */
42	  updateProfile: (body: UpdateProfileRequest) => Promise<User>;
43	  /** Re-run the `me()` probe (e.g. after returning from an OAuth callback). */
44	  refresh: () => Promise<void>;
45	};
46	
47	const AuthContext = createContext<AuthContextValue | null>(null);
48	
49	// Holds "who am I" for the whole app. Mounted in main.tsx around the router
50	// (mirrors FontProvider): one mount-time `me()` probe resolves the session
51	// cookie into a User, and the login/register/logout wrappers keep the state
52	// in sync afterwards. 401 from `me()` is the NORMAL signed-out answer (the
53	// api client deliberately doesn't swallow it), so it maps to "anonymous"
54	// without noise; anything else (network down) also lands on "anonymous" but
55	// flags `probeFailed`.
56	export function AuthProvider({ children }: { children: ReactNode }) {
57	  const [status, setStatus] = useState<AuthStatus>("loading");
58	  const [user, setUser] = useState<User | null>(null);
59	  const [probeFailed, setProbeFailed] = useState(false);
60	
61	  // Last-writer-wins guard: every state-writing operation claims a fresh
62	  // token at start and only applies its outcome while still the latest — so
63	  // a slow mount-time me() settling after a successful login can't clear the
64	  // fresh user, and a slow me() settling after logout can't resurrect one.
65	  const opToken = useRef(0);
66	
67	  const applyUser = useCallback((next: User) => {
68	    setUser(next);
69	    setStatus("authenticated");
70	    setProbeFailed(false);
71	  }, []);
72	
73	  const clearUser = useCallback(() => {
74	    setUser(null);
75	    setStatus("anonymous");
76	  }, []);
77	
78	  // The `me()` probe behind both refresh() and the api client's session
79	  // recovery. Returns whether the session is alive so the client knows to
80	  // retry the request that 401'd; the auth state is updated as a side effect
81	  // (unless a fresher operation has written meanwhile).
82	  const probe = useCallback(async (): Promise<boolean> => {
83	    const op = ++opToken.current;
84	    try {
85	      const next = await apiMe();
86	      if (op === opToken.current) applyUser(next);
87	      return true;
88	    } catch (error) {
89	      if (op === opToken.current) {
90	        clearUser();
91	        // A 401 is the clean "you're signed out" answer; anything else means
92	        // the probe itself failed (network, api down) — same UI state, but
93	        // distinguishable via the flag.
94	        setProbeFailed(!(error instanceof ApiError && error.status === 401));
95	      }
96	      return false;
97	    }
98	  }, [applyUser, clearUser]);
99	
100	  const refresh = useCallback(async () => {
101	    await probe();
102	  }, [probe]);
103	
104	  // The mount-time session probe. `refresh` never rejects, so no cleanup
105	  // race to guard beyond React batching the state updates.
106	  useEffect(() => {
107	    void refresh();
108	  }, [refresh]);
109	
110	  // Own the api client's 401 recovery: an unexpected 401 on a session-gated
111	  // route re-probes here — true (still signed in; the 401 was a one-off)
112	  // makes the client retry the request once, false means the probe already
113	  // flipped the whole app to signed-out.
114	  useEffect(() => {
115	    setSessionRecoveryHandler(probe);
116	    return () => setSessionRecoveryHandler(null);
117	  }, [probe]);
118	
119	  const login = useCallback(
120	    async (body: LoginRequest) => {
121	      const op = ++opToken.current;
122	      const next = await apiLogin(body);
123	      if (op === opToken.current) applyUser(next);
124	      return next;
125	    },
126	    [applyUser],
127	  );
128	
129	  const register = useCallback(
130	    async (body: RegisterRequest) => {
131	      const op = ++opToken.current;
132	      const next = await apiRegister(body);
133	      if (op === opToken.current) applyUser(next);
134	      return next;
135	    },
136	    [applyUser],
137	  );
138	
139	  // Same last-writer-wins discipline as login/register: a save that lands
140	  // after a logout must not resurrect the user.
141	  const updateProfile = useCallback(
142	    async (body: UpdateProfileRequest) => {
143	      const op = ++opToken.current;
144	      const next = await apiUpdateProfile(body);
145	      if (op === opToken.current) applyUser(next);
146	      return next;
147	    },
148	    [applyUser],
149	  );
150	
151	  const logout = useCallback(async () => {
152	    const op = ++opToken.current;
153	    try {
154	      await apiLogout();
155	    } catch (error) {
156	      // A 401 just means the session was already gone — that IS signed out.
157	      // Anything else propagates with the local state untouched.
158	      if (!(error instanceof ApiError && error.status === 401)) throw error;
159	    }
160	    if (op === opToken.current) clearUser();
161	  }, [clearUser]);
162	
163	  const value = useMemo(
164	    () => ({ status, user, probeFailed, login, register, logout, updateProfile, refresh }),
165	    [status, user, probeFailed, login, register, logout, updateProfile, refresh],
166	  );
167	
168	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
169	}
170	
171	export function useAuth(): AuthContextValue {
172	  const ctx = useContext(AuthContext);
173	  if (!ctx) throw new Error("useAuth must be used within <AuthProvider>");
174	  return ctx;
