11	// The account section of /settings (P5-5 — polish.md "Profiles"). P5-1 made a
12	// lobby seat's name the ACCOUNT's, resolved server-side and broadcast to the
13	// opponent and to spectators — which left a player named by whatever register
14	// picked, with nowhere to change it. This is that surface: the name, and the
15	// generated face (P5-2) drawn from the seed /auth/me now carries.
16	//
17	// It shows the REAL avatar, not a lookalike: the same component the lobby uses,
18	// fed the account's own seed, so "how you appear to other players" is a
19	// statement rather than an approximation. A rename reaches a lobby at the next
20	// hello (apps/api lobby/displayName.ts resolves the seat name there), so a
21	// player already seated elsewhere keeps the old name until they rejoin.
22	
23	const PANEL_CLASS = `rounded-2xl p-5 ${GLASS_PANEL}`;
24	const INPUT_CLASS = `${GLASS_INPUT} px-4 py-2.5 placeholder:text-white/35`;
25	const LABEL_CLASS = "mb-1.5 block text-xs font-medium text-white/55";
26	const SAVE_BUTTON_CLASS = `inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-full px-5 py-2.5 text-sm font-semibold disabled:cursor-not-allowed disabled:opacity-40 disabled:active:scale-100 ${GLASS_ACCENT_BUTTON}`;
