28	/** The register/login copy, narrowed to what a rename can actually fail on. */
29	function messageForError(error: unknown): string {
30	  if (!(error instanceof ApiError)) {
31	    return "Couldn't reach the server — check your connection and try again.";
32	  }
33	  switch (error.status) {
34	    case 400:
35	      return "That name doesn't fit — use 1 to 64 characters.";
36	    case 401:
37	      return "Your session expired — sign in again.";
38	    default:
39	      return "Something went wrong — try again.";
40	  }
