43	export function ProfileSection() {
44	  const { status, user } = useAuth();
45	
46	  // The panel keeps its place through the mount-time session probe: /settings
47	  // is vertically centered, so a section that appears late shifts the page.
48	  if (status === "loading") {
49	    return (
