55	  }
56	
57	  if (user === null) {
58	    return (
59	      <section className={PANEL_CLASS}>
60	        <h2 className="text-base font-semibold text-white/90">Profile</h2>
61	        <p className="mt-0.5 text-sm text-muted">
62	          <Link
63	            to="/login"
64	            state={{ from: "/settings" }}
65	            className="rounded font-medium text-white/80 underline-offset-4 transition-colors hover:text-white hover:underline focus:outline-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white/50"
66	          >
67	            Sign in
68	          </Link>{" "}
69	          to choose the name and face other players see.
70	        </p>
71	      </section>
72	    );
73	  }
74	
75	  // Keyed by account so switching users re-seeds the draft from the new name
76	  // instead of carrying the previous one into the field.
