80	function ProfileForm({ user }: { user: User }) {
81	  const { updateProfile, refresh } = useAuth();
82	  const [draft, setDraft] = useState(user.displayName);
83	  const [saving, setSaving] = useState(false);
84	  const [error, setError] = useState<string | null>(null);
85	  const [saved, setSaved] = useState(false);
86	  const nameId = useId();
87	
88	  const trimmed = draft.trim();
89	  // Same rule the server enforces; `maxLength` below keeps the upper bound
90	  // from ever being reachable, so this is really "not blank, not unchanged".
91	  const canSave = trimmed !== "" && trimmed.length <= 64 && trimmed !== user.displayName;
92	
93	  const handleSubmit = async (event: FormEvent) => {
94	    event.preventDefault();
95	    if (!canSave || saving) return;
96	    setError(null);
97	    setSaved(false);
98	    setSaving(true);
99	    try {
100	      // The provider adopts the api's answer, so the corner account control
101	      // and every other reader of `user` follow without a re-probe.
102	      await updateProfile({ displayName: trimmed });
103	      setSaved(true);
104	    } catch (caught) {
105	      setError(messageForError(caught));
106	      // A 401 here means the session died since the mount-time probe. /auth/*
107	      // is excluded from the client's retry-once recovery (there a 401 IS the
108	      // answer), so ask once: the app flips to signed-out and this section
109	      // becomes the sign-in prompt, which says it better than the error line.
110	      if (caught instanceof ApiError && caught.status === 401) void refresh();
111	    } finally {
112	      setSaving(false);
113	    }
114	  };
115	
116	  return (
117	    <section className={PANEL_CLASS}>
118	      <h2 className="text-base font-semibold text-white/90">Profile</h2>
119	      <p className="mt-0.5 text-sm text-muted">How you appear to other players.</p>
120	
121	      <form onSubmit={handleSubmit} noValidate className="mt-4 flex items-end gap-3">
122	        {/* Follows the field as you type — the initial is drawn from the name,
123	            so the face and the name can't disagree on screen. */}
124	        <PlayerAvatar name={draft} seed={user.avatarSeed} className="h-12 w-12" />
125	        <div className="min-w-0 flex-1">
126	          <label htmlFor={nameId} className={LABEL_CLASS}>
127	            Display name
128	          </label>
129	          <input
130	            id={nameId}
131	            type="text"
132	            value={draft}
133	            onChange={(e) => {
134	              setDraft(e.target.value);
135	              setSaved(false);
136	            }}
137	            maxLength={64}
138	            autoComplete="nickname"
139	            placeholder="Your name"
140	            className={INPUT_CLASS}
141	          />
142	        </div>
143	        <button type="submit" disabled={!canSave || saving} className={SAVE_BUTTON_CLASS}>
144	          {saving && <SpinnerIcon className="h-4 w-4 animate-spin" />}
145	          Save
146	        </button>
147	      </form>
148	
149	      <output className="mt-2 block empty:hidden">
150	        {error && <p className={`text-sm ${ERROR_TEXT}`}>{error}</p>}
151	        {saved && !error && <p className="text-sm text-white/55">Saved.</p>}
152	      </output>
153	
154	      <p className="mt-4 truncate border-t border-white/10 pt-4 text-xs text-white/35">
155	        Signed in as {user.email}
156	      </p>
157	    </section>
158	  );
159	}
