3	// A player's face (P5-2). Generated, not uploaded: the server hands out an
4	// `avatarSeed` derived from the account behind it (apps/api auth/avatar.ts), and
5	// the same seed always draws the same face — so an opponent you meet twice looks
6	// the same both times, with nothing stored and nothing to upload. When real
7	// avatars land, an image simply wins over this.
8	//
9	// Shared (not lobby-local) since P5-5: /settings shows a player their OWN face
10	// from the seed on `User`, and it must be the same drawing the lobby broadcasts,
11	// which means the same component, not a second one that looks similar.
12	//
13	// An ANONYMOUS seat (no account, so no seed) keeps the generic figure. That is
14	// the honest rendering: inventing a face from a throwaway per-lobby id would
15	// promise an identity that changes on the player's next visit.
16	
17	/** Two hues from the seed, far enough apart to read as a deliberate gradient.
18	    Saturation and lightness are FIXED so every generated avatar sits in the same
19	    register as the rest of the glass UI — the seed picks the hue, never how loud
20	    the result is, which is what stops one player's face glowing next to another's. */
21	function huesOf(seed: string): [number, number] {
22	  const value = Number.parseInt(seed, 16);
23	  const base = (Number.isNaN(value) ? 0 : value) % 360;
24	  return [base, (base + 55) % 360];
25	}
26	
27	/** The letter drawn over the gradient — the same "first character of the name"
28	    the account control in the corner already uses, so the two read as the same
29	    person. Falls back to nothing rather than a placeholder letter: an empty name
30	    is the server's fallback case, and a bare gradient beats a wrong initial. */
31	function initialOf(name: string): string {
32	  return name.trim().slice(0, 1).toUpperCase();
33	}
34	
35	export function PlayerAvatar({
36	  name,
37	  seed,
38	  className = "",
39	}: {
40	  name: string;
41	  /** The account token, or null for an anonymous seat. */
42	  seed: string | null;
43	  /** Sizing/positioning from the caller; the shape and ring are fixed here. */
44	  className?: string;
45	}) {
46	  const shell = `flex shrink-0 items-center justify-center rounded-full ring-1 ring-inset ring-white/10 ${className}`;
47	  if (seed === null) {
48	    return (
49	      // aria-hidden throughout: the name sits beside it in the DOM, so a screen
50	      // reader announcing the avatar as well would just say it twice.
51	      <div className={`bg-white/[0.06] text-white/45 ${shell}`} aria-hidden="true">
52	        <UserIcon className="h-5 w-5" />
53	      </div>
54	    );
55	  }
56	  const [from, to] = huesOf(seed);
57	  return (
58	    <div
59	      className={`text-sm font-semibold text-white/90 ${shell}`}
60	      aria-hidden="true"
61	      style={{
62	        backgroundImage: `linear-gradient(135deg, hsl(${from} 62% 52%), hsl(${to} 62% 38%))`,
63	      }}
64	    >
65	      {initialOf(name)}
66	    </div>
67	  );
68	}
