1	// The one owner of "load my deck library from the api" — shared by the
2	// decks page and the online deck picker, which used to hand-roll the same
3	// effect (parallel GET /decks + GET /folders, phase tracking, a Retry
4	// nonce). Session expiry needs no handling here: the api client's session
5	// recovery re-probes on an unexpected 401 and, when the session is really
6	// gone, AuthProvider flips the app to signed-out — the caller's sign-in
7	// prompt takes over from `phase` entirely.
8	
9	import { type Dispatch, type SetStateAction, useCallback, useEffect, useState } from "react";
10	import { listDecks, listFolders } from "../../lib/api";
11	import { type Deck, type Folder, fromDeckSummary } from "./data";
12	
13	export interface DeckLibrary {
14	  decks: Deck[];
15	  folders: Folder[];
16	  /** Exposed for the page's optimistic mutations. */
17	  setDecks: Dispatch<SetStateAction<Deck[]>>;
18	  setFolders: Dispatch<SetStateAction<Folder[]>>;
19	  /** "loading" until both lists land; a failure of either is "error" rather
20	      than a half-loaded grid. */
21	  phase: "loading" | "error" | "ready";
22	  /** Re-run the load (the error panel's Retry). */
23	  retry: () => void;
24	  /** Refetch both lists in place — honest recovery after a partially-applied
25	      compound mutation. Rejects on failure so the caller owns the surface. */
26	  resync: () => Promise<void>;
27	}
28	
29	/** Load the library while `enabled` (typically "the session is resolved and
30	    authenticated"; the picker also gates on its dialog being open). Each
31	    false→true transition refetches, so a reopened picker sees fresh lists. */
32	export function useDeckLibrary(enabled: boolean): DeckLibrary {
33	  const [decks, setDecks] = useState<Deck[]>([]);
34	  const [folders, setFolders] = useState<Folder[]>([]);
35	  const [phase, setPhase] = useState<"loading" | "error" | "ready">("loading");
36	  // Bumped by retry() to re-run the load effect.
37	  const [loadNonce, setLoadNonce] = useState(0);
38	
39	  useEffect(() => {
40	    // loadNonce has no value of its own — reading it here is what lets
41	    // retry() re-run this effect.
42	    void loadNonce;
43	    if (!enabled) return;
44	    let cancelled = false;
45	    setPhase("loading");
46	    Promise.all([listDecks(), listFolders()]).then(
47	      ([deckRows, folderRows]) => {
48	        if (cancelled) return;
49	        setDecks(deckRows.map(fromDeckSummary));
50	        setFolders(folderRows);
51	        setPhase("ready");
52	      },
53	      () => {
54	        if (!cancelled) setPhase("error");
55	      },
56	    );
57	    return () => {
58	      cancelled = true;
59	    };
60	  }, [enabled, loadNonce]);
61	
62	  const retry = useCallback(() => setLoadNonce((nonce) => nonce + 1), []);
63	
64	  const resync = useCallback(async () => {
65	    const [deckRows, folderRows] = await Promise.all([listDecks(), listFolders()]);
66	    setDecks(deckRows.map(fromDeckSummary));
67	    setFolders(folderRows);
68	  }, []);
69	
70	  return { decks, folders, setDecks, setFolders, phase, retry, resync };
71	}
