179	  /** Exact rarity string(s), e.g. "Double rare" — an array ORs within the dimension. */
180	  rarity?: string | string[];
181	  /** Pokémon stage(s), wire vocabulary ("Basic" | "Stage1" | "Stage2" | …). */
