1	// The decks page's client-side shapes plus the mapping from the api's wire
2	// types (M9 — the page loads the library from GET /decks + GET /folders
3	// instead of seed fixtures). The web `Deck` keeps its original vocabulary;
4	// `cardCount` is now the server-derived summed copy count, no longer a seed
5	// stand-in. Imports from @luminous/schema are types-only so the web bundle
6	// stays zod-free.
7	
8	import type { Deck as ApiDeck, DeckSummary } from "@luminous/schema";
9	import { deleteFolder, patchDeck, patchFolder } from "../../lib/api";
10	
11	export type Deck = {
12	  id: string;
13	  name: string;
14	  /** Owning folder, or null when the deck lives at the library root. */
15	  folderId: string | null;
16	  /** Summed copies across the deck's card list (server-derived). */
17	  cardCount: number;
18	  /** Base hue (0–360) for the deck's cover gradient, so the grid reads colourful.
19	      Still the backdrop behind a cover, and the whole cover when there is none. */
20	  tint: number;
21	  /** The card whose art fronts this deck (P5-3), or null for a deck with nothing
22	      to show yet — server-derived, so it follows the deck's contents. */
23	  coverCardId: string | null;
24	  /** Manual sort slot (server-persisted, global per user). The library array
25	      stays sorted by it — array order IS the manual order — so a reorder
26	      rewrites both together (see reorder.ts applyReorder). */
27	  position: number;
28	};
29	
30	export type Folder = {
31	  id: string;
32	  name: string;
33	  /** Owning folder, or null when the folder lives at the library root. Folders
34	      nest indefinitely by pointing at a parent folder. */
35	  parentId: string | null;
36	  /** Manual sort slot — same semantics as `Deck.position`. */
37	  position: number;
38	};
39	
40	/** A GET /decks list row as the grid renders it. */
41	export function fromDeckSummary(row: DeckSummary): Deck {
42	  return {
43	    id: row.id,
44	    name: row.name,
45	    folderId: row.folderId,
46	    cardCount: row.cardCount,
47	    tint: row.tint,
48	    coverCardId: row.coverCardId,
49	    position: row.position,
50	  };
51	}
52	
53	/** A full deck resource (create/patch responses) as the grid renders it —
54	    `cardCount` derived by summing the card list, matching the server's own
55	    summary maths. */
56	export function fromDeck(resource: ApiDeck): Deck {
57	  return {
58	    id: resource.id,
59	    name: resource.name,
60	    folderId: resource.folderId,
61	    cardCount: resource.cards.reduce((sum, card) => sum + card.count, 0),
62	    tint: resource.tint,
63	    // Only ever a just-CREATED deck here (the sole call site), which has no cards
64	    // and so no cover — the card back is the right face for it.
65	    coverCardId: null,
66	    position: resource.position,
67	  };
68	}
69	
70	// The server `Folder` wire shape ({id, name, parentId}) is exactly the web
71	// shape, so folders need no mapper — the api rows are used as-is.
72	
73	/** Delete a folder with the decks page's lift-up policy: its direct decks
74	    and subfolders move up to `parentId` first (rather than following the
75	    server's cascade, which would delete subfolders and drop decks to the
76	    root), so by the time DELETE runs the folder is empty and the cascade is
77	    a no-op. The child PATCHes fire in parallel — a partial failure leaves an
78	    arbitrary subset applied, which is fine because the caller resyncs the
79	    library from the server on ANY rejection here. */
80	export async function deleteFolderLiftingChildren(args: {
81	  folderId: string;
82	  /** The deleted folder's own parent — where the children land. */
83	  parentId: string | null;
84	  childFolderIds: string[];
85	  childDeckIds: string[];
86	}): Promise<void> {
87	  const { folderId, parentId, childFolderIds, childDeckIds } = args;
88	  await Promise.all([
89	    ...childFolderIds.map((id) => patchFolder(id, { parentId })),
90	    ...childDeckIds.map((id) => patchDeck(id, { folderId: parentId })),
91	  ]);
92	  await deleteFolder(folderId);
93	}
