1	import type { CSSProperties, ReactNode } from "react";
2	import { useTiltJuice } from "../../components/useTiltJuice";
3	import { cardBackSvgDataUrl } from "../playmat/pixi/cardBackSvg";
4	
5	// The deck preview's centrepiece: a faux-3D pile of cards whose top card is the
6	// exact blue "twilight" back the simulator renders. We reuse the simulator's
7	// SVG builder (pixi-free, see cardBackSvg.ts) so the two stay in lockstep, and
8	// paint it straight into the DOM as a data URL — built once at module load.
9	// Squared corners: the card div clips to rounded-[7px], so the SVG fills all the
10	// way to its corners and lets that clip do the rounding — otherwise the SVG's own
11	// rounded corners leave a crescent at each corner that shows the div's background.
12	const BLUE_BACK = cardBackSvgDataUrl("twilight", "blue", true);
13	
14	// One card in the pile, ordered back-to-front (later layers paint on top).
15	// Offsets are PERCENTAGES of the card's own size (CSS translate %), so the pile
16	// scales with the card.
17	type Layer = {
18	  tx: number;
19	  ty: number;
20	  rot: number;
21	  scale: number;
22	};
23	
24	const LAYERS: Layer[] = [
25	  // Squared-up stack: no rotation, no left/right stagger — the cards sit flush
26	  // and simply peek straight down behind the top one.
27	  { tx: 0, ty: 8, rot: 0, scale: 1 }, // back
28	  { tx: 0, ty: 6, rot: 0, scale: 1 },
29	  { tx: 0, ty: 4, rot: 0, scale: 1 },
30	  { tx: 0, ty: 2, rot: 0, scale: 1 }, // mid
31	  { tx: 0, ty: 0, rot: 0, scale: 1 }, // top
32	];
33	
34	// The cards under the top one show only their bottom edge peeking out, so they
35	// don't carry the blue back at all — they're a flat light blue matching the
36	// card back's inner border, so the slivers read as the cards' framed edges.
37	// Only the top card paints the real back over this.
38	const EDGE_COLOR = "#28345a";
39	
40	function layerStyle(l: Layer): CSSProperties {
41	  return {
42	    backgroundColor: EDGE_COLOR,
43	    transform: `translate(${l.tx}%, ${l.ty}%) rotate(${l.rot}deg) scale(${l.scale})`,
44	  };
45	}
46	
47	// Shared card styling for every layer in the pile, including a small drop shadow
48	// so each card lifts a touch off the one behind it.
49	const CARD_CLASS =
50	  "absolute inset-0 overflow-hidden rounded-[7px] bg-cover bg-center shadow-[0_2px_6px_rgba(0,0,0,0.35)]";
51	
52	// The top card sits a hair larger than the pile beneath it.
53	const TOP_CARD_SCALE = 1.01;
54	
55	/** Layered card-back pile that fills its container. The top card carries the
56	    `label` (deck name + count), printed into its lower edge; the cards beneath
57	    peek out below it to form the pile. Every deck — even a brand-new empty one —
58	    shows the full pile so each tile reads as a deck; the label is what tells
59	    empty from stocked. The cards are absolutely layered (inset-0) so they
60	    overlap, so this one sized container is the minimum the pile needs.
61	
62	    The top card carries the shared Balatro tilt + juice (the same hook the home
63	    menu and folder tiles use): it leans toward the pointer and pops on press
64	    while the pile beneath stays put, like lifting the top card off the deck. */
65	export function CardBackStack({
66	  label,
67	  coverUrl,
68	  juiceOnMount,
69	  dragActive,
70	}: {
71	  label?: ReactNode;
72	  /** Art for the TOP card (P5-3) — a deck's own headline card, chosen by the
73	      server. Absent, the stack stays the blue back it has always been, which is
74	      what a new or Pokémon-less deck should look like. Only the top card takes
75	      it: the ones behind are the deck's bulk, and printing the same scan three
76	      times would read as three copies rather than a stack. */
77	  coverUrl?: string;
78	  /** Pop the top card with a juice bounce when it first appears (new decks). */
79	  juiceOnMount?: boolean;
80	  /** Suppress the hover tilt while a drag is in flight (see useTiltJuice). */
81	  dragActive?: boolean;
82	}) {
83	  const { tiltRef, juiceLayerRef, juiceStyle, tiltStyle, handlers } = useTiltJuice<HTMLDivElement>({
84	    juiceOnMount,
85	    disabled: dragActive,
86	  });
87	  return (
88	    <div className="pointer-events-none relative aspect-[5/7] w-full">
89	      {LAYERS.map((l, i) => {
90	        // The back cards are static; only the top card is interactive.
91	        if (i !== LAYERS.length - 1) {
92	          return <div key={i} style={layerStyle(l)} className={CARD_CLASS} />;
93	        }
94	        return (
95	          // Outer layer carries the transient juice (squash + wobble); the inner
96	          // card carries the pointer tilt and is the lone interactive surface.
97	          <div
98	            key={i}
99	            ref={juiceLayerRef}
100	            style={{ ...juiceStyle, transform: `scale(${TOP_CARD_SCALE}) ${juiceStyle.transform}` }}
101	            className="absolute inset-0"
102	          >
103	            <div
104	              ref={tiltRef}
105	              {...handlers}
106	              style={{ backgroundImage: `url("${coverUrl ?? BLUE_BACK}")`, ...tiltStyle }}
107	              className={`pointer-events-auto cursor-pointer select-none ${CARD_CLASS}`}
108	            >
109	              {label && (
110	                <>
111	                  {/* A scrim, only under real art (P5-3). The name used to sit on
112	                      a flat blue back where white read cleanly; over a card scan
113	                      — flames, holo foil, a 190 in bold — it was barely legible.
114	                      Beneath the label, above the art, and absent for a coverless
115	                      deck so the original look is untouched. */}
116	                  {coverUrl !== undefined && (
117	                    <div
118	                      aria-hidden="true"
119	                      className="absolute inset-x-0 bottom-0 h-1/2 rounded-b-[7px] bg-gradient-to-t from-black/90 via-black/55 to-transparent"
120	                    />
121	                  )}
122	                  <div className="absolute inset-x-0 bottom-0 px-6 pb-6">{label}</div>
123	                </>
124	              )}
125	            </div>
126	          </div>
127	        );
128	      })}
129	    </div>
130	  );
131	}
