// signed-out caller should hear "unauthorized", not a critique of their body.
authRoutes.patch(
  "/me",
  requireUser,
  zValidator("json", updateProfileRequestSchema, (result, c) =>
    result.success ? undefined : invalidBody(c, result.error),
  ),
  async (c) => {
    const row = c.get("user");
