authRoutes.post("/logout", async (c) => {
  const token = readCookie(c.req.header("Cookie"), SESSION_COOKIE);
  if (token !== null) {
    await drizzle(c.env.DB)
      .delete(sessions)
      .where(eq(sessions.id, await hashSessionToken(token)));
  }
  c.header("Set-Cookie", clearedSessionCookie());
