import { Link } from "react-router-dom";
import { AppBackdrop } from "../../components/AppBackdrop";
import { ArrowLeftIcon, SettingsIcon } from "../../components/icons";
import { GLASS_GHOST_BUTTON, GLASS_ICON_TILE, GLASS_PANEL } from "../../lib/glass";
import { useFont } from "./FontProvider";
import { FONT_OPTIONS, fontFamilyValue } from "./fonts";
import { ProfileSection } from "./ProfileSection";

export function Settings() {
  const { fontId, setFontId } = useFont();

  return (
    <AppBackdrop>
      <main className="mx-auto flex min-h-svh w-full max-w-lg flex-col justify-center gap-6 px-6 py-12">
        <header className="flex items-center gap-3">
          <div className={`h-12 w-12 ${GLASS_ICON_TILE}`}>
            <SettingsIcon className="h-6 w-6" />
          </div>
          <h1 className="text-2xl font-semibold tracking-tight text-white/90">Settings</h1>
        </header>

        <ProfileSection />

        <section className={`rounded-2xl p-5 ${GLASS_PANEL}`}>
          <div className="flex items-center justify-between gap-4">
            <div>
              <h2 className="text-base font-semibold text-white/90">Font</h2>
              <p className="text-sm text-muted">Typeface used across the app.</p>
            </div>
            <select
              value={fontId}
              onChange={(e) => setFontId(e.target.value)}
              aria-label="App font"
              className="cursor-pointer rounded-lg bg-white/[0.06] px-3 py-2 text-sm font-medium text-white/90 outline-none ring-1 ring-inset ring-white/10 transition-colors hover:bg-white/[0.09] focus-visible:ring-2 focus-visible:ring-white/50"
            >
              {FONT_OPTIONS.map((f) => (
                <option
                  key={f.id}
                  value={f.id}
                  style={{ fontFamily: fontFamilyValue(f.family) }}
                  className="bg-surface text-white"
                >
                  {f.label}
                </option>
              ))}
            </select>
          </div>

          {/* Live preview — inherits the body font, which updates instantly. */}
          <p className="mt-4 border-t border-white/10 pt-4 text-lg text-white/80">
            The quick brown fox jumps over the lazy dog — 0123456789
          </p>
        </section>

        <Link
          to="/"
          className={`group inline-flex items-center gap-2 self-start rounded-full px-4 py-2 text-sm font-medium ${GLASS_GHOST_BUTTON}`}
        >
          <ArrowLeftIcon className="h-4 w-4 transition-transform group-hover:-translate-x-0.5" />
          Back to home
        </Link>
      </main>
    </AppBackdrop>
  );
}

export const GLASS_PANEL =
  "bg-white/[0.045] shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_8px_30px_rgba(0,0,0,0.40)] ring-1 ring-inset ring-white/10 backdrop-blur-md";

/** Round filter-rail toggle beside a page's search field, sized to match the
    field's height (p-2.5 + a 20px glyph ≈ the input's py-2.5 + text-sm line).
    /decks and the builder share it byte-for-byte; the open/active vs idle
    paint (bg/text/ring tints) stays at the call sites. */
export const GLASS_FILTER_TOGGLE = `relative inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full p-2.5 ring-1 ring-inset backdrop-blur-md transition-all active:scale-95 ${FOCUS_RING}`;

/** Pill text-input paint (auth form fields, the decks/builder search bars).
    Padding and placeholder tint stay at the call site (the builder's search
    placeholder is deliberately lighter). The deck picker's in-dialog search
    keeps its own heavier fill (bg-white/[0.06], no blur) — not standardised. */
export const GLASS_INPUT =
  "w-full rounded-full bg-white/[0.045] text-sm text-white/90 ring-1 ring-inset ring-white/10 backdrop-blur-md transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-white/50";

/** The app's shared error red (deck legality warnings, auth/lobby form errors,
    rolled-back mutation notices). */

